MERGE INTO ROLES r USING (SELECT 'ADMIN' ROLE_NAME, 'Full system administrator' DESCRIPTION FROM DUAL) x
ON (r.ROLE_NAME = x.ROLE_NAME)
WHEN NOT MATCHED THEN INSERT (ROLE_NAME, DESCRIPTION) VALUES (x.ROLE_NAME, x.DESCRIPTION);
MERGE INTO ROLES r USING (SELECT 'EMPLOYEE' ROLE_NAME, 'Standard application user' DESCRIPTION FROM DUAL) x
ON (r.ROLE_NAME = x.ROLE_NAME)
WHEN NOT MATCHED THEN INSERT (ROLE_NAME, DESCRIPTION) VALUES (x.ROLE_NAME, x.DESCRIPTION);

MERGE INTO PERMISSIONS p USING (SELECT 'USER_READ' NAME, 'Read users' D FROM DUAL) x ON (p.PERMISSION_NAME=x.NAME) WHEN NOT MATCHED THEN INSERT (PERMISSION_NAME,DESCRIPTION) VALUES(x.NAME,x.D);
MERGE INTO PERMISSIONS p USING (SELECT 'USER_CREATE' NAME, 'Create users' D FROM DUAL) x ON (p.PERMISSION_NAME=x.NAME) WHEN NOT MATCHED THEN INSERT (PERMISSION_NAME,DESCRIPTION) VALUES(x.NAME,x.D);
