INSERT INTO ROLE_PERMISSIONS (ROLE_ID,PERMISSION_ID)
SELECT r.ROLE_ID,p.PERMISSION_ID FROM ROLES r CROSS JOIN PERMISSIONS p
WHERE r.ROLE_NAME='ADMIN' AND NOT EXISTS (SELECT 1 FROM ROLE_PERMISSIONS rp WHERE rp.ROLE_ID=r.ROLE_ID AND rp.PERMISSION_ID=p.PERMISSION_ID);
INSERT INTO ROLE_PERMISSIONS (ROLE_ID,PERMISSION_ID)
SELECT r.ROLE_ID,p.PERMISSION_ID FROM ROLES r JOIN PERMISSIONS p ON p.PERMISSION_NAME IN ('ACCESS_REQUEST_READ','ACCESS_REQUEST_CREATE','2FA_MANAGE')
WHERE r.ROLE_NAME='EMPLOYEE' AND NOT EXISTS (SELECT 1 FROM ROLE_PERMISSIONS rp WHERE rp.ROLE_ID=r.ROLE_ID AND rp.PERMISSION_ID=p.PERMISSION_ID);
